int r[64];

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    /* N = 2: impossivel (media de 2 numeros distintos nao pode pertencer a eles) */
    if (N == 2) {
        printf("-1\n");
        return 0;
    }

    if (N & 1) {
        /* N impar: preenchimento sequencial funciona.
           Linha i tem media ((i-1)N + (N+1)/2), presente na coluna (N+1)/2.
           Coluna j tem media ((N-1)/2)N + j, presente na linha (N+1)/2. */
        int x = 1;
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (j) putchar(' ');
                printf("%d", x++);
            }
            putchar('\n');
        }
        return 0;
    }

    /* N par, N >= 4: quadrado da forma v(i,j) = W*r[i] + r[j] + 1
       com r = (0, 1, ..., N-2, 3N/2 - 1).
       soma(r) = N^2/2 => media(r) = N/2, que pertence a r.
       Escolhendo W = 3N/2 > max(r) - min(r), todos os N^2 valores sao distintos.
       Media da linha i  = W*r[i] + N/2 + 1 = v(i, N/2+1)  (presente na linha).
       Media da coluna j = W*(N/2) + r[j] + 1 = v(N/2+1, j) (presente na coluna).
       Maior valor = (3N/2)^2 = 3600 <= 10^6 para N <= 40. */
    {
        int m = N / 2;
        int W = 3 * m;   /* 3N/2 */
        int X = W - 1;   /* 3N/2 - 1 */
        for (int i = 0; i < N - 1; i++) r[i] = i;
        r[N - 1] = X;

        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (j) putchar(' ');
                printf("%d", W * r[i] + r[j] + 1);
            }
            putchar('\n');
        }
    }
    return 0;
}
